  "cmd/entire/cli/checkpoint/shadow_ref.go",
  "cmd/entire/cli/checkpoint/store.go"
];

function resolveConflicts(content, choice) {
  const lines = content.split("\n");
  const out = [];
  let state = "normal";
  let ours = [];
  let theirs = [];
  for (const line of lines) {
    if (state === "normal" && line.startsWith("<<<<<<< ")) {
      state = "ours";
      ours = [];
      theirs = [];
    } else if (state === "ours" && line === "=======") {
      state = "theirs";
    } else if (state === "theirs" && line.startsWith(">>>>>>> ")) {
      out.push(...(choice === "ours" ? ours : theirs));
      state = "normal";
    } else if (state === "ours") {
      ours.push(line);
    } else if (state === "theirs") {
      theirs.push(line);
    } else {
      out.push(line);
    }
  }
  if (state !== "normal") throw new Error("unterminated conflict");
  return out.join("\n");
}

async function replaceViaPatch(path, content) {
  const del = await tools.apply_patch(`*** Begin Patch\n*** Delete File: ${path}\n*** End Patch`);
  const addBody = content.split("\n").map(line => `+${line}`).join("\n");
  const add = await tools.apply_patch(`*** Begin Patch\n*** Add File: ${path}\n${addBody}\n*** End Patch`);
  return [del, add];
}

