	})
	if err := store.Write(ctx, SessionSummary{
		CheckpointID: cpID,
		SessionID:    "session-001",
		Summary:      &Summary{Intent: "first summary"},
	}); err != nil {
		t.Fatalf("Write(SessionSummary) error = %v", err)
	}

	first, err := store.ReadSessionMetadata(ctx, cpID, 0)
