function resolveConflicts(content) {
  const lines = content.split("\n");
  const out = [];
  let state = "normal";
  let ours = [];
  let theirs = [];
  for (const line of lines) {
    if (state === "normal" && line.startsWith("<<<<<<< ")) {
      state = "ours";
      ours = [];
      theirs = [];
    } else if (state === "ours" && line === "=======") {
      state = "theirs";
    } else if (state === "theirs" && line.startsWith(">>>>>>> ")) {
      out.push(...ours);
      state = "normal";
    } else if (state === "ours") {
      ours.push(line);
    } else if (state === "theirs") {
      theirs.push(line);
    } else {
      out.push(line);
    }
  }
  if (state !== "normal") throw new Error("unterminated conflict");
  return out.join("\n");
}

