		// The ref resolved but its commit object doesn't — corruption/IO, not an
		// absent checkpoint. Surface it instead of masking as "not found".
		return nil, fmt.Errorf("read checkpoint commit %s for %s: %w", ref.Hash(), cid, err)
	}
