	legacy := id.MustCheckpointID("a1b2c3d4e5f6")
	refsWrite(t, store, legacy, "s-legacy", "t")
	_, err := store.repo.Reference("refs/entire/checkpoints/f6/a1b2c3d4e5f6", true)
